/** Merge overlapping half-open reservations without modifying the input. */
export function mergeReservations(rows) {
  const sorted = Array.from(rows, (row) => {
    const start = row?.start;
    const end = row?.end;
    if (!Number.isInteger(start) || !Number.isInteger(end) || start >= end) {
      throw new RangeError('Reservation endpoints must be integers with start < end');
    }
    return { start, end };
  });
  sorted.sort((a, b) => a.start - b.start);

  const merged = [];
  for (const next of sorted) {
    const current = merged[merged.length - 1];
    if (current && next.start < current.end) {
      current.end = Math.max(current.end, next.end);
    } else {
      merged.push(next);
    }
  }
  return merged;
}

export function mergeReservations(rows) {
  const intervals = rows.map(({ start, end }) => {
    if (!Number.isInteger(start) || !Number.isInteger(end) || start >= end) {
      throw new RangeError('Reservation endpoints must be integers with start < end');
    }
    return { start, end };
  });

  intervals.sort((a, b) => a.start - b.start);

  const merged = [];
  for (const interval of intervals) {
    const current = merged[merged.length - 1];
    if (current && interval.start < current.end) {
      if (interval.end > current.end) current.end = interval.end;
    } else {
      merged.push({ start: interval.start, end: interval.end });
    }
  }
  return merged;
}

export function mergeReservations(rows) {
  const sorted = rows.map((row) => {
    if (!row || !Number.isInteger(row.start) || !Number.isInteger(row.end) || row.start >= row.end) {
      throw new RangeError('Invalid interval endpoints');
    }
    return { start: row.start, end: row.end };
  }).sort((a, b) => a.start - b.start);

  const merged = [];
  for (const interval of sorted) {
    const current = merged[merged.length - 1];
    if (current && interval.start < current.end) {
      current.end = Math.max(current.end, interval.end);
    } else {
      merged.push(interval);
    }
  }
  return merged;
}
